// 响应体解密密钥
var key_hex = "ea9d9d4f9a983fe6f6382f29c7b46b8d6dc47abc6da36662e6ddff8c78902f65"
// 请求和响应  1 不反转 2 反转
var version = 2

if (typeof Buffer === "undefined") {
    const CryptoJS = require("crypto-js");
    CryptoJS.enc.Uint8Array = {
        /**
         * WordArray转Uint8Array
         * @param wordArray
         * @returns {Uint8Array}
         * CryptoJS.enc.Uint8Array.stringify  WordArrayToUin8Array
         * CryptoJS.enc.Uint8Array.parse      Uin8ArrayToWordArray
         *
         * 抓取代码网址：https://blog.csdn.net/weixin_36123300/article/details/114348044
         */
        stringify: function (wordArray) {
            var words = wordArray.words;
            var sigBytes = wordArray.sigBytes;
            var u8 = new Uint8Array(sigBytes);
            for (var i = 0; i < sigBytes; i++) {
                var byte = (words[i >>> 2] >>> (24 - (i % 4) * 8)) & 0xff;
                u8[i] = byte;
            }
            return u8;
        },
        /**
         * Uint8Array转WordArray
         * @param u8arr
         * @returns {WordArray}
         */
        parse: function (u8arr) {
            var len = u8arr.length;
            var words = [];
            for (var i = 0; i < len; i++) {
                words[i >>> 2] |= (u8arr[i] & 0xff) << (24 - (i % 4) * 8);
            }
            return CryptoJS.lib.WordArray.create(words, len);
        }
    };
    const Buffer = {}
    Buffer.from = function(data, encoding) {
        /**
         * @type {Uint8Array}
         */
        let u8 = null;
        if (encoding === "hex"){
            u8 = CryptoJS.enc.Uint8Array.stringify(CryptoJS.enc.Hex.parse(data));
        } else {
            u8 = new Uint8Array(data);
        }
        u8.toString = function(encoding) {
            if (encoding.toLowerCase() === "utf8"){
                return CryptoJS.enc.Uint8Array.parse(u8).toString(CryptoJS.enc.Utf8)
            }
        }
        return u8;
    }
    globalThis.Buffer = Buffer
}

/**
 * 十六进制字符串转 Buffer
 */
function hexToBytes(hexStr) {
    hexStr = hexStr.replace(/\s+/g, '').toLowerCase();
    if (hexStr.length % 2 !== 0) {
        throw new Error('十六进制字符串长度必须为偶数');
    }
    return Buffer.from(hexStr, 'hex');
}

const Uo = {
    encryptRequest: async function (e, t, n = 1) {
        if (32 !== t.length)
            throw new Error("密钥长度必须为32字节");
        // const a = new Uint8Array(12);
        // globalThis.crypto.getRandomValues(a);
        const a = new Uint8Array([0x1, 0x2, 0x3, 0x4, 0x5, 0x6, 0x7, 0x8, 0x9, 0xa, 0xb, 0xc]);
        const o = {
            name: "AES-GCM",
            iv: a
        }
            , r = await crypto.subtle.importKey("raw", t, "AES-GCM", !1, ["encrypt"])
            , s = new Uint8Array(await crypto.subtle.encrypt(o, r, e));

        2 === n && function (e) {
            for (let t = 0, n = e.length - 1; t < n; t++,
                n--) {
                const a = e[t];
                e[t] = e[n],
                    e[n] = a
            }
        }(s);
        const i = new Uint8Array(1 + a.length + s.length);
        return i[0] = 2 === n ? 2 : 1,
            i.set(a, 1),
            i.set(s, 1 + a.length),
            i
    },
    decryptResponse: function (e, t, n = 1) {
        if (32 !== t.length)
            throw new Error("密钥长度必须为32字节");
        if (e.length < 41)
            throw new Error("密文长度不足");
        const a = e[0]
            , o = e.subarray(1, 25)
            , r = e.subarray(25)
            , s = 2 === a ? r.slice().reverse() : r
            , i = new Bo(t).open(o, s);
        if (!i)
            throw new Error("认证失败");
        return i
    }
};

