/**
 * 解密数据（使用libsodium兼容Python逻辑）
 */
async function decryptData(encryptedHex, keyHex=key_hex, version=version) {
    await sodium.ready; // 初始化libsodium
    try {
        const encrypted = hexToBytes(encryptedHex);
        const key = hexToBytes(keyHex);

        if (encrypted.length < 41) {
            throw new Error("加密数据长度不足");
        }

        const dataVersion = encrypted[0];
        console.log(`数据版本号: ${dataVersion}`);

        const nonce = encrypted.slice(1, 25);
        console.log(`Nonce长度: ${nonce.length}字节`);

        let ciphertext = encrypted.slice(25);
        console.log(`密文(含标签)长度: ${ciphertext.length}字节`);

        if (dataVersion === 2) {
            console.log("版本号为2，执行密文反转");
            ciphertext = Buffer.from(ciphertext.reverse());
        }

        // 使用libsodium的XChaCha20-Poly1305解密（完全对齐Python）
        let de = null;
        if (sodium.crypto_aead_xchacha20poly1305_ietf_decrypt) {
            de = sodium.crypto_aead_xchacha20poly1305_ietf_decrypt;
        } else {
            de = sodium.default.crypto_aead_xchacha20poly1305_ietf_decrypt;
        }
        // drpy-node需要Buffer转换为Uint8Array类型
        const plaintext = de(
            null,                // 明文输出缓冲区
            new Uint8Array(ciphertext),          // 密文+标签
            null,                // 附加数据（空）
            new Uint8Array(nonce),               // 24字节nonce
            new Uint8Array(key)                  // 32字节密钥
        );        
        const plaintextStr = Buffer.from(plaintext).toString('utf8');
        console.log("\n解密成功！");
        return JSON.parse(plaintextStr);
    } catch (error) {
        console.error("解密失败:", error.message);
        throw error;
    }
}

